    for i, (lab, key) in enumerate(rows):
        y = 3 - i
        lv, hv = ((lambda q, u: q.to(u).magnitude)(getattr({'light': SimpleNamespace(count=60000, maximum=Q_(9876.583008, 'µs'), over_threshold=123, p50=Q_(203.4583282, 'µs'), p99=Q_(251.875, 'µs'), p999=Q_(2347.520792, 'µs')), 'heavy': SimpleNamespace(count=60000, maximum=Q_(35822.5, 'µs'), over_threshold=401, p50=Q_(202.375, 'µs'), p99=Q_(597.6087299, 'µs'), p999=Q_(4945.666833, 'µs'))}[k], key), 'us') for k in ('light', 'heavy'))
        ax.barh(y + 0.18, lv, color=GRAY, height=0.32)
