def queue(step):
    w, h = (14.6, 4.4)
    fig, ax = canvas(w, h)

    def row(y, title, color):
        ax.text(0.1, y + 1.45, title, fontsize=FS, fontweight='bold', color=color, va='center')
        box(ax, 0.1, y, 2.3, 1.0, 'Chunk policy\nwrites at 20 Hz', fc=BLUE_L, ec=BLUE, ls='--', fs=FS_S)
        box(ax, 11.9, y, 2.6, 1.0, 'Permission tick\nreads at 1 kHz', fc=GREEN_L, ec=GREEN_D, fs=FS_S)
    row(2.55, 'FIFO queue (event messages): every proposal is kept and read in order', RED_D)
    arrow(ax, 2.4, 3.05, 3.0, 3.05, BLUE)
    for i, lab in enumerate(['#9', '#8', '#7', '#6', '#5']):
        box(ax, 3.1 + i * 1.45, 2.65, 1.25, 0.8, lab, fc='white', ec=BLUE, fs=FS)
    ax.text(3.1, 2.42, 'newest', ha='left', va='top', fontsize=FS_S, color=GRAY)
    ax.text(3.1 + 4 * 1.45 + 1.25, 2.42, 'oldest', ha='right', va='top', fontsize=FS_S, color=GRAY)
    arrow(ax, 10.35, 3.05, 11.9, 3.05, RED)
    ax.text(11.1, 3.32, '#5', fontsize=FS, color=RED_D, fontweight='bold', ha='center')
    ax.text(14.5, 2.4, 'acts on the oldest plan', fontsize=FS_S, color=RED_D, fontweight='bold', ha='right', va='top')
    if step >= 2:
        row(0.1, 'Mailbox (state message): one slot, overwritten in place', GREEN_D)
        arrow(ax, 2.4, 0.6, 5.3, 0.6, BLUE)
        box(ax, 5.4, 0.2, 2.4, 0.8, '#9', fc='white', ec=GREEN_D, fs=FS, lw=1.6)
        arrow(ax, 7.8, 0.6, 11.9, 0.6, GREEN_D)
        ax.text(9.85, 0.83, '#9, the freshest', fontsize=FS, color=GREEN_D, fontweight='bold', ha='center')
    save_slot(fig, f'queue_step{step}')

def mailbox_meas(step):
    w, h = (11.0, 3.9)
    fig, ax = plot_axes(w, h, left=0.2, bottom=1.0, right=0.2, top=0.1)
    rows = [('Blocking mutex', 'mbx_mutex_max', RED, '3,766 µs; 99 reads over 1 ms'), ('One try-lock (as ros2_control)', 'mbx_trylock_max', GREEN, '4.4 µs'), ('One-attempt seqlock', 'mbx_seqlock_max', GREEN_D, '3.7 µs; 358 torn reads rejected')]
    for i, (lab, key, c, txt) in enumerate(rows):
        y = 2 - i
        ax.text(0.12, y + 0.26, lab, fontsize=FS_S, fontweight='bold', color=c, va='bottom')
        if step >= 2:
            mx = {'#DC2626': 3766.0, '#059669': 4.4, '#047857': 3.7}[c]
            ax.barh(y - 0.1, mx, left=0.1, color=c, height=0.36)
            ax.text(mx * 1.25, y - 0.1, txt, fontsize=FS_S, color=c, va='center', fontweight='bold', zorder=5, bbox=dict(fc='white', ec='none', pad=0.5))
        else:
            ax.text(0.15, y - 0.1, '?', fontsize=FS, color=c, va='center', fontweight='bold')
    ax.axvline(1000.0, color=SLATE, ls='--', lw=1.2)
    ax.text(1000.0 * 1.15, 2.45, 'one tick', fontsize=FS_S, color=SLATE, va='bottom')
    ax.set_xscale('log')
    ax.set_xlim(0.1, 30000000.0)
    ax.set_ylim(-0.55, 2.7)
    ax.set_yticks([])
    ax.minorticks_off()
    ax.set_xticks([0.1, 1, 10, 100, 1000, 10000])
    ax.set_xticklabels(['0.1', '1', '10', '100', '1,000', '10,000'])
    ax.spines['left'].set_visible(False)
    ax.set_xlabel('Longest time the reader spent getting a proposal (µs, log scale)', fontsize=FS_S)
    save_slot(fig, f'mailbox_meas_step{step}')

def seqlock(step):
    w, h = (14.6, 4.9)
    fig, ax = canvas(w, h)
    cw = 4.75
    cases = [('1  Clean exchange', ['7', '8'], 'reads 8, then 8:\naccept the chunk', GREEN_D), ('2  Tick preempts a write', ['9', '10'], 'reads 9 (odd): reject,\nkeep the active chunk', AMBER), ('3  Host stalls', ['10', '10'], 'reads 10 again: nothing new,\nlease keeps counting', SLATE)]
    for k, (title, ctr, out, c) in enumerate(cases):
        x0 = 0.1 + k * (cw + 0.1)
        if step < k + 1:
            continue
        box(ax, x0, 0.1, cw, 4.7, fc='white', ec=GRAY_L, lw=1.0)
        ax.text(x0 + 0.15, 4.5, title, fontsize=FS, fontweight='bold', color=c, va='center')
        ax.text(x0 + 0.15, 3.85, 'Writer', fontsize=FS_S, color=BLUE, va='center')
        ax.text(x0 + 0.15, 2.85, 'Counter', fontsize=FS_S, color=SLATE, va='center')
        ax.text(x0 + 0.15, 1.85, 'Tick', fontsize=FS_S, color=GREEN_D, va='center')
        if k == 0:
            box(ax, x0 + 1.5, 3.6, 1.9, 0.5, 'copy frame', fc=BLUE_L, ec=BLUE, ls='--', fs=FS_S)
            box(ax, x0 + 1.5, 2.6, 0.9, 0.5, '7 odd', fc=AMBER_L, ec=AMBER, fs=FS_S)
            box(ax, x0 + 3.45, 2.6, 0.9, 0.5, '8', fc=GREEN_L, ec=GREEN, fs=FS_S)
            for xx in (3.65, 4.15):
                arrow(ax, x0 + xx, 2.6, x0 + xx, 2.1, GREEN_D)
        elif k == 1:
            box(ax, x0 + 1.5, 3.6, 0.7, 0.5, '', fc=BLUE_L, ec=BLUE, ls='--')
            ax.text(x0 + 2.3, 3.85, 'paused', fontsize=FS_S, color=GRAY, va='center')
            box(ax, x0 + 3.55, 3.6, 0.6, 0.5, '', fc=BLUE_L, ec=BLUE, ls='--')
            box(ax, x0 + 1.5, 2.6, 2.4, 0.5, '9 odd', fc=AMBER_L, ec=AMBER, fs=FS_S)
            box(ax, x0 + 3.95, 2.6, 0.7, 0.5, '10', fc=GREEN_L, ec=GREEN, fs=FS_S)
            arrow(ax, x0 + 2.6, 2.6, x0 + 2.6, 2.1, AMBER)
            arrow(ax, x0 + 4.3, 2.6, x0 + 4.3, 2.1, GREEN_D)
        else:
            ax.text(x0 + 2.8, 3.85, 'no frame arrives', fontsize=FS_S, color=GRAY, va='center', ha='center')
            box(ax, x0 + 1.5, 2.6, 3.1, 0.5, '10', fc=GREEN_L, ec=GREEN, fs=FS_S)
            for xx in (2.4, 3.8):
                arrow(ax, x0 + xx, 2.6, x0 + xx, 2.1, SLATE)
        ax.plot([x0 + 1.3, x0 + cw - 0.1], [1.85, 1.85], color=GREEN_D, lw=1.2)
        ax.text(x0 + cw / 2, 1.0, out, fontsize=FS_S, ha='center', va='center', color=c, fontweight='bold')
    save_slot(fig, f'seqlock_step{step}')

def lease(step):
    w, h = (14.6, 4.9)
    fig, ax = plot_axes(w, h, left=2.4, bottom=1.0, right=0.2, top=0.15)
    yP, yA, yL, yD = (3.0, 2.0, 1.0, 0.0)
    infer, renew, lease_ms = (40.0, 50.0, 60.0)
    first, last, stall = (40.0, 90.0, 100.0)
    expiry, brake, x_end = (150.0, 172.0, 210)
    ax.barh(yP, infer, left=0, color=BLUE, height=0.45)
    ax.barh(yP, infer, left=renew, color=BLUE, height=0.45)
    for x in (first, last):
        ax.plot([x], [yA], marker='v', ms=9, color=GREEN_D)
    ax.text(last, yA + 0.32, 'last admission', fontsize=FS_S, color=GREEN_D, ha='center')
    ax.add_patch(Rectangle((first, yL - 0.22), lease_ms, 0.44, fc='none', ec=GREEN, ls='--', lw=1.2))
    if step == 1:
        ax.barh(yD, stall, left=0, color=SLATE, height=0.45)
        ax.text(stall / 2, yD, 'tracking admitted setpoints', color='white', fontsize=FS_S, ha='center', va='center')
    if step >= 2:
        ax.add_patch(Rectangle((stall, yP - 0.22), x_end - stall, 0.44, fc=RED_L, ec=RED, hatch='///', lw=1))
        ax.text(stall + 25, yP + 0.33, 'stalled', fontsize=FS_S, color=RED_D, ha='center', fontweight='bold')
        ax.barh(yL, lease_ms, left=last, color=GREEN, height=0.44)
        ax.text(last + lease_ms / 2, yL, 'lease 60 ms', color='white', fontsize=FS, fontweight='bold', ha='center', va='center')
        ax.barh(yD, expiry, left=0, color=SLATE, height=0.45)
        ax.text(expiry / 2, yD, 'tracking the last admitted chunk', color='white', fontsize=FS_S, ha='center', va='center')
    if step >= 3:
        ax.barh(yD, brake - expiry, left=expiry, color=AMBER, height=0.45)
        ax.barh(yD, x_end - brake, left=brake, color=RED, height=0.45)
        ax.text((brake + x_end) / 2, yD, 'stop', color='white', fontsize=FS_S, ha='center', va='center', fontweight='bold')
        ax.axvline(expiry, color=GREEN_D, ls='--', lw=1)
        ax.axvline(brake, color=RED, ls='--', lw=1.2)
        ax.text((brake + x_end) / 2, yA, 'tick + bus\n+ onset 22 ms', fontsize=FS_S - 1, color=AMBER, ha='center', va='center', fontweight='bold')
        ax.annotate('', xy=(brake, -0.72), xytext=(last, -0.72), arrowprops=dict(arrowstyle='<->', color=RED_D, lw=1.2))
        ax.text((last + brake) / 2 - 5, -0.64, '82 ms = 123 mm to brake onset', fontsize=FS_S, color=RED_D, ha='center', va='bottom', fontweight='bold', zorder=5, bbox=dict(fc='white', ec='none', pad=0.5))
    ax.set_yticks([yP, yA, yL, yD])
    ax.set_yticklabels(['Chunk policy', 'Admission', 'Lease', 'Drives'], fontsize=FS, fontweight='bold')
    ax.tick_params(axis='y', length=0)
    ax.set_xlim(0, x_end)
    ax.set_ylim(-0.95, 3.55)
    ax.set_xlabel('Time (ms)', fontsize=FS_S)
    ax.spines['left'].set_visible(False)
    save_slot(fig, f'lease_step{step}')

def openvla():
    w, h = (9.2, 3.8)
    fig, ax = plot_axes(w, h, left=0.2, bottom=1.0, right=0.2, top=0.45)
    for i, ((lab, _), key) in enumerate(zip([('FP16', Q_(840.0, 'ms')), ('FP8', Q_(471.0, 'ms')), ('INT4', Q_(336.0, 'ms'))], ('vla_fp16', 'vla_fp8', 'vla_int4'))):
        y = 2 - i
        t = {'FP16': 840.0, 'FP8': 471.0, 'INT4': 336.0}[lab]
        ax.barh(y, t, color=NAVY, height=0.42)
        ax.text(t + 12, y, f"{lab}  { {'FP16': '840', 'FP8': '471', 'INT4': '336'}[lab]} ms", fontsize=FS_S, va='center', color=NAVY, fontweight='bold')
    ax.axvline(60.0, color=GREEN_D, ls='-', lw=2)
    ax.text(60.0, 2.62, 'lease 60', color=GREEN_D, fontsize=FS_S, ha='center', va='bottom', fontweight='bold')
    ax.axvline(258.3, color=RED, ls='--', lw=1.6)
    ax.text(258.3, 2.62, 'pre-brake ceiling 258.3', color=RED, fontsize=FS_S, ha='left', va='bottom', fontweight='bold')
    ax.set_xlim(0, 1060)
    ax.set_ylim(-0.5, 2.55)
    ax.set_yticks([])
    ax.spines['left'].set_visible(False)
    ax.set_xlabel('OpenVLA-7B, measured time per frame (ms)', fontsize=FS_S)
    save_slot(fig, 'openvla')

def leaserule(step):
    w, h = (14.6, 4.7)
    fig, ax = plot_axes(w, h, left=1.2, bottom=1.25, right=0.2, top=0.2)
    ceil, up0 = (258.3333333, 236.3333333)
    up_age, upper = (184.7333333, 121.4226133)
    cols = [('Pre-brake\nceiling', 0, ceil, RED, '258.3'), ('tick, bus,\nonset', up0, ceil, AMBER, '−' + '22.0'), ('observation\nage\n(Lecture 8)', up_age, up0, AMBER, '−' + '51.6'), ('dispatch to\nadmission\n(Lecture 13)', upper, up_age, AMBER, '−' + '63.3'), ('Upper limit\non the lease', 0, upper, GREEN_D, '121.4')]
    labels = []
    for i, (lab, lo, hi, c, txt) in enumerate(cols):
        ax.bar(i, hi - lo, bottom=lo, color=c, width=0.6)
        ax.text(i, hi + 6, txt, ha='center', va='bottom', fontsize=FS, color=c, fontweight='bold')
        labels.append(lab)
    if step >= 2:
        floor_ms, lease_ms = (55.0, 60.0)
        ax.bar(5.2, floor_ms, color=BLUE, width=0.45)
        ax.text(5.2, floor_ms + 6, '55', ha='center', va='bottom', fontsize=FS, color=BLUE, fontweight='bold')
        ax.bar(5.8, lease_ms, color=GREEN, width=0.45)
        ax.text(5.8, lease_ms + 6, '60', ha='center', va='bottom', fontsize=FS, color=GREEN_D, fontweight='bold')
        labels_extra = True
    else:
        labels_extra = False
    ax.set_xticks(list(range(5)) + ([5.2, 5.8] if labels_extra else []))
    ax.set_xticklabels(labels + (['floor', 'lease'] if labels_extra else []), fontsize=FS_S)
    ax.set_xlim(-0.5, 6.2)
    ax.set_ylim(0, 300)
    ax.set_ylabel('ms', fontsize=FS_S)
    ax.tick_params(axis='x', length=0)
    save_slot(fig, f'leaserule_step{step}')

def timers():
    w, h = (8.2, 5.0)
    fig, ax = canvas(w, h)
    items = [('Evidence deadline passes', NAVY), ('Chunk lease (60 ms) expires', GREEN_D), ('Host heartbeat silent 30 ms', SLATE), ('Protective scanner trips', RED)]
    for i, (lab, c) in enumerate(items):
        y = 4.0 - i * 0.95
        box(ax, 0.1, y, 4.3, 0.72, lab, fc='white', ec=c, tc=c, fs=FS_S, bold=False)
        arrow(ax, 4.4, y + 0.36, 5.0, 2.92, c, lw=1.2)
    box(ax, 5.0, 2.35, 3.1, 1.15, 'Earliest one\nends authority', fc=RED_L, ec=RED, tc=RED_D, bold=True, fs=FS_S)
    arrow(ax, 6.55, 2.35, 6.55, 1.72, RED)
    box(ax, 5.0, 1.05, 3.1, 0.65, 'State-matched stop', fc='white', ec=RED, tc=RED_D, fs=FS_S, bold=True)
    box(ax, 0.1, 0.1, 8.0, 0.8, 'Only an admitted chunk renews the lease.\nA heartbeat never does.', fc=GREEN_L, ec=GREEN, tc=GREEN_D, fs=FS_S, bold=True)
    save_slot(fig, 'timers')

def events():
    w, h = (14.6, 2.9)
    fig, ax = canvas(w, h)
    x0, scale = (0.9, 12.6 / 200.0)
    t = [0, 51.6, 114.91072, 196.91072]
    names = ['capture', 'dispatch', 'admission', 'brake onset']
    ax.plot([x0, x0 + t[-1] * scale], [1.6, 1.6], color=SLATE, lw=2)
    for ti, n in zip(t, names):
        x = x0 + ti * scale
        ax.plot([x, x], [1.4, 1.8], color=SLATE, lw=2)
        ax.text(x, 1.95, n, ha='center', va='bottom', fontsize=FS, fontweight='bold', color=RED_D if n == 'brake onset' else TEXT)
    spans = [('observation age\n51.6 ms (Lecture 8)', AMBER), ('dispatch to admission\n63.3 ms (Lecture 13)', AMBER), ('stalled proposer 82 ms\n(lease + tick + bus + onset)', GREEN_D)]
    for k, (lab, c) in enumerate(spans):
        a, b = (x0 + t[k] * scale, x0 + t[k + 1] * scale)
        ax.annotate('', xy=(b, 1.15), xytext=(a, 1.15), arrowprops=dict(arrowstyle='<->', color=c, lw=1.4))
        ax.text((a + b) / 2, 1.0, lab, ha='center', va='top', fontsize=FS_S, color=c)
    save_slot(fig, 'events')

def rta(step):
    w, h = (14.6, 4.3)
    fig, ax = plot_axes(w, h, left=2.6, bottom=1.0, right=0.3, top=0.35)
    y1, y2 = (1.0, 0.0)
    c0, c, b, i_, r, d = (_NUMS[k] for k in ('c_unloaded', 't_wcet', 'rta_b', 'rta_i', 'rta_r', 'rta_d'))
    ax.barh(y1, c0, color=GRAY, height=0.45)
    ax.text(c0 + 4, y1, '135 µs, one unloaded run', va='center', fontsize=FS_S, color=GRAY)
    ax.barh(y2, c0, color=GREEN, height=0.45)
    ax.add_patch(Rectangle((c0, y2 - 0.225), c - c0, 0.45, fc=GREEN_L, ec=GREEN, hatch='///'))
    ax.text(c / 2, y2 - 0.38, 'C = 250 (declared WCET)', ha='center', va='top', fontsize=FS_S, color=GREEN_D, fontweight='bold')
    if step >= 2:
        ax.barh(y2, b, left=c, color=AMBER, height=0.45)
        ax.barh(y2, i_, left=c + b, color='#B45309', height=0.45)
        ax.text(c + b / 2, y2 + 0.33, 'B 50', ha='center', va='bottom', fontsize=FS_S, color=AMBER, fontweight='bold')
        ax.text(c + b + i_ / 2, y2 + 0.33, 'I 40', ha='center', va='bottom', fontsize=FS_S, color='#B45309', fontweight='bold')
        ax.text(r + 4, y2 - 0.38, 'R = 340', ha='left', va='top', fontsize=FS, color=TEXT, fontweight='bold')
    if step >= 3:
        ax.axvline(d, color=RED, ls='--', lw=1.6)
        ax.text(d - 4, 1.5, 'deadline D = 400 µs', color=RED, fontsize=FS_S, fontweight='bold', va='center', ha='right')
        ax.annotate('', xy=(d, y2), xytext=(r, y2), arrowprops=dict(arrowstyle='<->', color=RED_D, lw=1.2))
        ax.text(d + 4, y2, 'margin 60', va='center', fontsize=FS_S, color=RED_D, fontweight='bold')
    ax.set_yticks([y1, y2])
    ax.set_yticklabels(['Observed', 'Bound'], fontsize=FS, fontweight='bold')
    ax.tick_params(axis='y', length=0)
    ax.spines['left'].set_visible(False)
    ax.set_xlim(0, 480)
    ax.set_ylim(-0.75, 1.75)
    ax.set_xlabel("Time after the tick's release (µs)", fontsize=FS_S)
    save_slot(fig, f'rta_step{step}')

